#import <Foundation/Foundation.h>
#import <AVFoundation/AVFoundation.h>
#import <AppKit/AppKit.h>
int main(int argc,const char **argv){@autoreleasepool{
 NSString *mode=@(argv[1]); AVURLAsset *a=[AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:@(argv[2])] options:nil];
 if([mode isEqual:@"info"]){NSMutableArray *tracks=[NSMutableArray array];for(AVAssetTrack *t in a.tracks){[tracks addObject:@{@"type":t.mediaType,@"fps":@(t.nominalFrameRate),@"width":@(t.naturalSize.width),@"height":@(t.naturalSize.height),@"start":@(CMTimeGetSeconds(t.timeRange.start)),@"duration":@(CMTimeGetSeconds(t.timeRange.duration)),@"transform":@"see track"}];} NSData *j=[NSJSONSerialization dataWithJSONObject:@{@"duration":@(CMTimeGetSeconds(a.duration)),@"tracks":tracks} options:NSJSONWritingPrettyPrinted error:nil]; puts([[NSString alloc]initWithData:j encoding:NSUTF8StringEncoding].UTF8String);
 }else if([mode isEqual:@"frames"]){AVAssetImageGenerator *g=[[AVAssetImageGenerator alloc]initWithAsset:a];g.appliesPreferredTrackTransform=YES;g.maximumSize=CGSizeMake(1280,720);g.requestedTimeToleranceBefore=kCMTimeZero;g.requestedTimeToleranceAfter=kCMTimeZero;
 for(int i=4;i<argc;i++){NSError *err=nil;CMTime actual;CGImageRef im=[g copyCGImageAtTime:CMTimeMakeWithSeconds(atof(argv[i]),60000) actualTime:&actual error:&err];if(im){NSBitmapImageRep *rep=[[NSBitmapImageRep alloc]initWithCGImage:im];NSData *d=[rep representationUsingType:NSBitmapImageFileTypeJPEG properties:@{NSImageCompressionFactor:@0.88}];[d writeToFile:[NSString stringWithFormat:@"%s_%s.jpg",argv[3],argv[i]] atomically:YES];CGImageRelease(im);printf("%s -> %.4f\n",argv[i],CMTimeGetSeconds(actual));}else NSLog(@"%@",err);}
 }else if([mode isEqual:@"audio"]){NSError *err=nil;AVAssetReader *r=[[AVAssetReader alloc]initWithAsset:a error:&err];AVAssetReaderTrackOutput *o=[[AVAssetReaderTrackOutput alloc]initWithTrack:[a tracksWithMediaType:AVMediaTypeAudio][0] outputSettings:@{AVFormatIDKey:@(kAudioFormatLinearPCM),AVSampleRateKey:@8000,AVNumberOfChannelsKey:@1,AVLinearPCMBitDepthKey:@16,AVLinearPCMIsFloatKey:@NO,AVLinearPCMIsBigEndianKey:@NO,AVLinearPCMIsNonInterleaved:@NO}];[r addOutput:o];[r startReading];NSMutableData *d=[NSMutableData data];CMSampleBufferRef s;while((s=[o copyNextSampleBuffer])){CMBlockBufferRef b=CMSampleBufferGetDataBuffer(s);size_t len=CMBlockBufferGetDataLength(b);void *p=malloc(len);CMBlockBufferCopyDataBytes(b,0,len,p);[d appendBytes:p length:len];free(p);CFRelease(s);}[d writeToFile:@(argv[3]) atomically:YES];printf("bytes %lu status %ld\n",(unsigned long)d.length,(long)r.status);
 }}}
